var getModuleObjectVersion string

// GetModuleObjectsCmd represents the module-object command
var GetModuleObjectsCmd = &cobra.Command{
	Example: "  tptctl get module-objects",
	Long:    "Get module objects from the system.",
	PreRun:  CommandPreRunFunc,
	Run: func(cmd *cobra.Command, args []string) {
		apiClient, _, apiEndpoint, requestedControlPlane := GetClientContext(cmd)

		switch getModuleObjectVersion {
		case "v0":
			// get module objects
			moduleObjects, err := client_v0.GetModuleObjects(apiClient, apiEndpoint)
			if err != nil {
				cli.Error("failed to retrieve module objects", err)
				os.Exit(1)
			}

			// write the output
			if len(*moduleObjects) == 0 {
				cli.Info(fmt.Sprintf(
					"No module objects currently managed by %s threeport control plane",
					requestedControlPlane,
				))
				os.Exit(0)
			}
			if err := outputGetv0ModuleObjectsCmd(
				moduleObjects,
				apiClient,
				apiEndpoint,
			); err != nil {
				cli.Error("failed to produce output", err)
				os.Exit(1)
			}
		default:
			cli.Error("", errors.New("unrecognized object version"))
			os.Exit(1)
		}
	},
	Short:        "Get module objects from the system",
	SilenceUsage: true,
	Use:          "module-objects",
}

